create table fria_assessment (id varchar(255) primary key, ai_system_id varchar(255) not null references ai_system(id), jurisdiction varchar(255) not null, template_version varchar(255) not null, affected_groups varchar(4000) not null, assumptions varchar(4000) not null, mitigations varchar(4000) not null, dpia_uri varchar(2000) not null, dpia_sha256 varchar(255) not null, signed_by varchar(255) not null, signed_at varchar(255) not null);
